  SUBSTITUTE = { accuracy = 0, ailment = "none", ailmentChance = 0, category = "unique", critRate = 0, damageClass = "status", drain = 0, effect = "Transfers 1/4 the user’s max HP into a doll that absorbs damage and causes most negative move effects to fail. If the user leaves the field, the doll will vanish. If the user cannot pay the HP cost, this move will fail. The doll takes damage as normal, using the user’s stats and types, and will break when its HP reaches zero. Self-inflicted damage from confusion or recoil is not absorbed. Healing effects from opponents ignore the doll and heal the user as normal. Moves that work based on the user’s HP still do so; the doll’s HP does not influence any move. The doll will block major status effects, confusion, and flinching. The effects of Smelling Salts and Wake-Up Slap do not trigger against a doll, even if the Pokémon behind the doll has the appropriate major status effect. Multi-turn trapping moves like Wrap will hit the doll for their regular damage, but the multi-turn trapping and damage effects will not activate. Moves blocked or damage absorbed by the doll do not count as hitting the user or inflicting damage for any effects that respond to such, e.g., Avalanche, Counter, or a Rowap Berry. Magic Coat still works as normal, even against moves the doll would block. Opposing Pokémon that damage the doll with a leech move like Absorb are healed as normal. It will also block Acupressure, Block, the curse effect of Curse, Dream Eater, Embargo, Flatter, Gastro Acid, Grudge, Heal Block, Leech Seed, Lock-On, Mean Look, Mimic, Mind Reader, Nightmare, Pain Split, Psycho Shift, Spider Web, Sketch, Swagger, Switcheroo, Trick, Worry Seed, and Yawn. A Pokémon affected by Yawn before summoning the doll will still fall to sleep. The doll blocks Intimidate, but all other abilities act as though the doll did not exist. If the user has an ability that absorbs moves of a certain type for HP (such as Volt Absorb absorbing Thunder Wave), such moves will not be blocked. Life Orb and berries that cause confusion still work as normal, but their respective HP loss and confusion are absorbed/blocked by the doll. The user is still vulnerable to damage inflicted when entering or leaving the field, such as by Pursuit or Spikes; however, the doll will block the poison effect of Toxic Spikes. The doll is passed on by Baton Pass. It keeps its existing HP, but uses the replacement Pokémon’s stats and types for damage calculation. All other effects work as normal.", effectChance = 0, engineMove = true, flinchChance = 0, gen1Effect = "NO_ADDITIONAL_EFFECT", gen1EffectModeled = false, gen2Effect = "EFFECT_NORMAL_HIT", gen2EffectModeled = false, generation = "generation-i", healing = 0, id = "SUBSTITUTE", maxHits = 0, maxTurns = 0, minHits = 0, minTurns = 0, moveId = 164, name = "Substitute", power = 0, pp = 10, priority = 0, shortEffect = "Transfers 1/4 of the user’s max HP into a doll, protecting the user from further damage or status changes until it breaks.", slug = "substitute", statChance = 0, statChanges = {}, strippedId = "SUBSTITUTE", target = "user", type = "NORMAL" },
